{"version":3,"sources":["../scss/profile_store.scss","profile_store.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAGA;EACE,aAAA;EACA,SAAA;EACA,+CAAA;ACFF;;ADKA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;ACFF;ADGE;EACE,aAAA;EACA,mBAAA;EACA,yBAAA;EACA,eAAA;EACA,SAAA;ACDJ;ADIE;EACE,WAAA;EACA,gBAAA;EACA,yBAAA;EACA,YAAA;EACA,kBAAA;EEzBA,uCAAA;EACA,gBFyBoC;EExBpC,kBAAA;EACA,YCHW;EDIX,eFsB8B;ACElC;ADDI;EACE,yBAAA;ACGN;ADCE;EACE,kBAAA;ACCJ;ADEE;EACE,gBAAA;ACAJ;ADGE;EExCE,uCAAA;EACA,gBFwCoC;EEvCpC,kBAAA;EACA,YCHW;EDIX,eFqC8B;EAC9B,eAAA;ACGJ;ADDI;EACE,UAAA;ACGN;;ADEA;EACE,kBAAA;EACA,yBAAA;EACA,kBAAA;EACA,gBAAA;ACCF;ADAE;EACE,gBAAA;EACA,gBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;EACA,kBAAA;ACEJ;ADEI;EACE,qBAAA;EACA,UAAA;EACA,cAAA;ACAN;;ADKA;EACE,wBAAA;EACA,qBAAA;EACA,UAAA;EACA,kBAAA;EACA,MAAA;EACA,QAAA;EACA,WAAA;EACA,YAAA;EACA,2FAAA;EACA,eAAA;EACA,UAAA;ACFF;ADIE;EAEE,WAAA;EACA,cAAA;EACA,WAAA;EACA,WAAA;EACA,gBAAA;EACA,kBAAA;EACA,QAAA;EACA,QAAA;EACA,UAAA;EACA,wBAAA;ACHJ;ADKE;EACE,yBAAA;ACHJ;;ADOA;EAEI;IACE,WAAA;IACA,eAAA;ECLJ;EDMI;IACA,yBAAA;ECJJ;EDQE;IACE,2BAAA;ECNJ;EDSA;IACE,4DAAA;ECPF;AACF","file":"profile_store.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.form__wrapper {\n  display: grid;\n  gap: 10px;\n  grid-template-columns: minmax(300px, 1fr) 220px;\n}\n\n.main__info {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  & label {\n    display: flex;\n    align-items: center;\n    justify-content: flex-end;\n    flex-wrap: wrap;\n    gap: 10px;\n  }\n\n  & select, input, textarea {\n    width: 100%;\n    max-width: 320px;\n    border: 1px solid $gray;\n    padding: 5px;\n    border-radius: 7px;\n    @include fonts($defaultColor, 14px, 400);\n    &:focus {\n      border: 1px solid #3779eb;\n    }\n  }\n\n  & option {\n    padding-left: 15px;\n  }\n\n  & button {\n    max-width: 200px;\n  }\n\n  & p {\n    @include fonts($defaultColor, 14px, 400);\n    flex: 0 1 200px;\n\n    & span {\n      color: red;\n    }\n  }\n}\n\n.photo_img {\n  position: relative;\n  border: 1px solid $asideLinksColor;\n  border-radius: 3px;\n  max-width: 120px;\n  & img {\n    max-width: 120px;\n    max-height: 85px;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n    border-radius: 3px;\n  }\n\n  &:hover {\n    .delete_img {\n      transition: 0.3s ease;\n      opacity: 1;\n      display: block;\n    }\n  }\n}\n\n.delete_img {\n  border-radius: 0 3px 0 0;\n  transition: 0.3s ease;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 15px;\n  height: 15px;\n  background: url(../img/icons/krestik.svg) no-repeat 100% 100% /100% 100%, rgb(0, 0, 0, 0.5);\n  cursor: pointer;\n  z-index: 1;\n\n  &::after,\n  &::before {\n    content: \"\";\n    display: block;\n    width: 100%;\n    height: 2px;\n    background: #fff;\n    position: absolute;\n    top: 45%;\n    right: 0;\n    z-index: 1;\n    transform: rotate(45deg);\n  }\n  &::before {\n    transform: rotate(-45deg);\n  }\n}\n\n@media(max-width: 992px) {\n  .main__info {\n    & select, input, textarea {\n      width: 100%;\n      max-width: none;\n      &:focus {\n      border: 1px solid #3779eb;\n    }\n    }\n\n    & label {\n      justify-content: flex-start;\n    }\n  }\n  .form__wrapper {\n    grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));\n  }\n}\n\n",".form__wrapper {\n  display: grid;\n  gap: 10px;\n  grid-template-columns: minmax(300px, 1fr) 220px;\n}\n\n.main__info {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.main__info label {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n.main__info select, .main__info input, .main__info textarea {\n  width: 100%;\n  max-width: 320px;\n  border: 1px solid #D4D4D4;\n  padding: 5px;\n  border-radius: 7px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.main__info select:focus, .main__info input:focus, .main__info textarea:focus {\n  border: 1px solid #3779eb;\n}\n.main__info option {\n  padding-left: 15px;\n}\n.main__info button {\n  max-width: 200px;\n}\n.main__info p {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  flex: 0 1 200px;\n}\n.main__info p span {\n  color: red;\n}\n\n.photo_img {\n  position: relative;\n  border: 1px solid #307792;\n  border-radius: 3px;\n  max-width: 120px;\n}\n.photo_img img {\n  max-width: 120px;\n  max-height: 85px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n  border-radius: 3px;\n}\n.photo_img:hover .delete_img {\n  transition: 0.3s ease;\n  opacity: 1;\n  display: block;\n}\n\n.delete_img {\n  border-radius: 0 3px 0 0;\n  transition: 0.3s ease;\n  opacity: 0;\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 15px;\n  height: 15px;\n  background: url(../img/icons/krestik.svg) no-repeat 100% 100%/100% 100%, rgba(0, 0, 0, 0.5);\n  cursor: pointer;\n  z-index: 1;\n}\n.delete_img::after, .delete_img::before {\n  content: \"\";\n  display: block;\n  width: 100%;\n  height: 2px;\n  background: #fff;\n  position: absolute;\n  top: 45%;\n  right: 0;\n  z-index: 1;\n  transform: rotate(45deg);\n}\n.delete_img::before {\n  transform: rotate(-45deg);\n}\n\n@media (max-width: 992px) {\n  .main__info select, .main__info input, .main__info textarea {\n    width: 100%;\n    max-width: none;\n  }\n  .main__info select:focus, .main__info input:focus, .main__info textarea:focus {\n    border: 1px solid #3779eb;\n  }\n  .main__info label {\n    justify-content: flex-start;\n  }\n  .form__wrapper {\n    grid-template-columns: repeat(auto-fill, minmax(400px, 1fr));\n  }\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}